// --- Tab: Questions ---

function QuestionsTab({
  questions,
  selectedQuestionIndex,
  onSelectQuestion,
  onUpdateQuestion,
  onAddQuestion,
  onAddOption,
  onUpdateOption,
  onDeleteOption,
}: {
  questions: Question[];
  selectedQuestionIndex: number;
  onSelectQuestion: (index: number) => void;
  onUpdateQuestion: (field: string, value: string) => void;
  onAddQuestion: () => void;
  onAddOption: () => void;
  onUpdateOption: (optionId: string, value: string) => void;
  onDeleteOption: (optionId: string) => void;
}) {
  const selectedQuestion = questions[selectedQuestionIndex];

  return (
    <Layout>
      {/* Left sidebar - question list */}
      <Layout.Section variant="oneThird">
        <Card>
          <BlockStack gap="200">
            <Text as="h3" variant="headingSm" fontWeight="semibold">
              Questions ({questions.length})
            </Text>
            <Divider />
            <BlockStack gap="100">
              {questions.map((q, index) => (
                <div
                  key={q.id}
                  style={{
                    padding: "10px 12px",
                    borderRadius: "var(--p-border-radius-200)",
                    cursor: "pointer",
                    background:
                      index === selectedQuestionIndex
                        ? "var(--p-color-bg-surface-secondary-hover)"
                        : "transparent",
                    border:
                      index === selectedQuestionIndex
                        ? "1px solid var(--p-color-border-emphasis)"
                        : "1px solid transparent",
                  }}
                  onClick={() => onSelectQuestion(index)}
                  role="button"
                  tabIndex={0}
                  onKeyDown={(e) => {
                    if (e.key === "Enter" || e.key === " ") {
                      e.preventDefault();
                      onSelectQuestion(index);
                    }
                  }}
                >
                  <InlineStack gap="200" blockAlign="center">
                    <div
                      style={{
                        width: 24,
                        height: 24,
                        borderRadius: "50%",
                        background: "var(--p-color-bg-fill-emphasis)",
                        color: "#fff",
                        display: "flex",
                        alignItems: "center",
                        justifyContent: "center",
                        fontSize: 12,
                        fontWeight: 600,
                        flexShrink: 0,
                      }}
                    >
                      {index + 1}
                    </div>
                    <BlockStack gap="050">
                      <Text as="p" variant="bodySm" fontWeight="semibold" truncate>
                        {q.title || "Untitled question"}
                      </Text>
                      <Text as="p" variant="bodySm" tone="subdued">
                        {questionTypeOptions.find((o) => o.value === q.type)?.label || q.type}
                      </Text>
                    </BlockStack>
                  </InlineStack>
                </div>
              ))}
            </BlockStack>
            <Button onClick={onAddQuestion} fullWidth>
              + Add question
            </Button>
          </BlockStack>
        </Card>
      </Layout.Section>

      {/* Right panel - question editor */}
      <Layout.Section>
        <Card>
          {selectedQuestion ? (
            <BlockStack gap="400">
              <Text as="h3" variant="headingSm" fontWeight="semibold">
                Question {selectedQuestionIndex + 1}
              </Text>
              <TextField
                label="Question title"
                value={selectedQuestion.title}
                onChange={(value) => onUpdateQuestion("title", value)}
                autoComplete="off"
              />
              <Select
                label="Question type"
                options={questionTypeOptions}
                value={selectedQuestion.type}
                onChange={(value) => onUpdateQuestion("type", value)}
              />
              <Divider />
              <Text as="h3" variant="headingSm" fontWeight="semibold">
                Answer options
              </Text>
              <BlockStack gap="200">
                {selectedQuestion.options.map((option) => (
                  <InlineStack key={option.id} gap="200" blockAlign="end">
                    <div style={{ flex: 1 }}>
                      <TextField
                        label=""
                        labelHidden
                        value={option.label}
                        onChange={(value) => onUpdateOption(option.id, value)}
                        autoComplete="off"
                        placeholder="Answer option"
                      />
                    </div>
                    <Button
                      tone="critical"
                      variant="plain"
                      onClick={() => onDeleteOption(option.id)}
                    >
                      Delete
                    </Button>
                  </InlineStack>
                ))}
              </BlockStack>
              <Button onClick={onAddOption}>+ Add answer</Button>
            </BlockStack>
          ) : (
            <Text as="p" variant="bodyMd" tone="subdued">
              Select a question from the sidebar to edit it.
            </Text>
          )}
        </Card>
      </Layout.Section>
    </Layout>
  );
}

// --- Tab: Product Mapping ---

function ProductMappingTab({
  questions,
  onAddProduct,
  onRemoveProduct,
}: {
  questions: Question[];
  onAddProduct: (questionId: string, optionId: string, product: string) => void;
  onRemoveProduct: (questionId: string, optionId: string, product: string) => void;
}) {
  const [browseValue, setBrowseValue] = useState<Record<string, string>>({});

  return (
    <BlockStack gap="600">
      {questions.map((question) => (
        <Card key={question.id}>
          <BlockStack gap="400">
            <Text as="h3" variant="headingSm" fontWeight="semibold">
              {question.title}
            </Text>
            <Divider />
            <BlockStack gap="400">
              {question.options.map((option) => {
                const fieldKey = `${question.id}-${option.id}`;
                return (
                  <BlockStack key={option.id} gap="200">
                    <Text as="p" variant="bodyMd" fontWeight="medium">
                      {option.label}
                    </Text>
                    <InlineStack gap="200" blockAlign="end">
                      <div style={{ flex: 1 }}>
                        <TextField
                          label=""
                          labelHidden
                          value={browseValue[fieldKey] || ""}
                          onChange={(value) =>
                            setBrowseValue((prev) => ({
                              ...prev,
                              [fieldKey]: value,
                            }))
                          }
                          autoComplete="off"
                          placeholder="Search products..."
                        />
                      </div>
                      <Button
                        onClick={() => {
                          const value = browseValue[fieldKey];
                          if (value && value.trim()) {
                            onAddProduct(question.id, option.id, value.trim());
                            setBrowseValue((prev) => ({
                              ...prev,
                              [fieldKey]: "",
                            }));
                          }
                        }}
                      >
                        Browse products
                      </Button>
                    </InlineStack>
                    {option.products.length > 0 && (
                      <InlineStack gap="200">
                        {option.products.map((product) => (
                          <Tag
                            key={product}
                            onRemove={() =>
                              onRemoveProduct(question.id, option.id, product)
                            }
                          >
                            {product}
                          </Tag>
                        ))}
                      </InlineStack>
                    )}
                  </BlockStack>
                );
              })}
            </BlockStack>
          </BlockStack>
        </Card>
      ))}
    </BlockStack>
  );
}

